t='.(((((........)((((....))))..)))).......'
stack=[]
pairs={}
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[(j,i)]='('
print('pairs:',sorted(pairs))
print('5-14:',(5,14) in pairs)
"

